"""Stochastic Multi-Scenario Tree Optimizer for Multi-Gameweek Horizons (Pillar 2).Replaces fragile single-path deterministic projections with multi-scenario recourse evaluation:- Nominal Scenario (p=0.50): Projections hold as modeled.- Rotation Shock Scenario (p=0.25): High-fatigue / European cup assets face rotation risk.- Availability Stress Scenario (p=0.25): Flagged / injury-prone assets face reduced minutes.Evaluates candidates on expected recourse utility, downside risk (CVaR), and optionality value."""from dataclasses import dataclassfrom typing import Anyimport numpy as npimport pandas as pd@dataclassclass StochasticScenario:    name: str    probability: float    description: str    scenario_projections: dict[int, pd.DataFrame]@dataclassclass StochasticPlanEvaluation:    plan_id: str    label: str    transfers_in: list[int]    transfers_out: list[int]    hit_cost: int    scenario_utilities: dict[str, float]    expected_stochastic_utility: float    downside_worst_case: float    robustness_index: float  # Expected utility penalized by scenario dispersion    recommendation_tier: str    downside_cvar: float = 0.0@dataclassclass ParetoPlanPoint:    lambda_risk: float    strategy_profile: str  # "MAX_UPSIDE", "RISK_NEUTRAL", "BALANCED_CONTENDER", "DEFENSIVE_PRESERVATION"    best_plan_id: str    label: str    expected_stochastic_utility: float    downside_worst_case: float    downside_cvar: float    robustness_score: float    transfers_in: list[int]    transfers_out: list[int]    hit_cost: int    rationale: strclass StochasticScenarioOptimizer:    """    Evaluates multi-period moves across a probability tree of future scenarios.    """    def __init__(self, risk_aversion_lambda: float = 0.25):        """        risk_aversion_lambda: Weight on downside dispersion penalty in robustness score.        """        self.risk_lambda = risk_aversion_lambda    def generate_scenario_tree(        self,        horizon_projections: dict[int, pd.DataFrame],        target_gw: int,    ) -> list[StochasticScenario]:        """        Generates 3 calibrated branching scenarios for future weeks (t > target_gw).        """        scenarios: list[StochasticScenario] = []        # 1. Nominal Scenario        scenarios.append(            StochasticScenario(                name="nominal",                probability=0.50,                description="Expected baseline: models and predicted minutes hold as projected.",                scenario_projections={gw: df.copy() for gw, df in horizon_projections.items()},            )        )        # 2. Rotation Shock Scenario        # In weeks after target_gw, players with high minutes or European fixtures face 20% fatigue rotation        rot_projs: dict[int, pd.DataFrame] = {}        for gw, df in horizon_projections.items():            df_rot = df.copy()            if gw > target_gw and "expected_points" in df_rot.columns:                # Assets priced >= 8.0m or high expected points face tactical rotation variance                is_premium = df_rot.get("value", 50.0) >= 80.0                high_xp = df_rot["expected_points"] >= 4.5                rot_mask = is_premium | high_xp                df_rot.loc[rot_mask, "expected_points"] = (df_rot.loc[rot_mask, "expected_points"] * 0.85).round(2)            rot_projs[gw] = df_rot        scenarios.append(            StochasticScenario(                name="rotation_shock",                probability=0.25,                description="Midweek fatigue / rotation shock: premium and high-xP assets face tactical rotation in subsequent weeks.",                scenario_projections=rot_projs,            )        )        # 3. Availability Stress Scenario        # Players with any injury news or < 100% chance of playing suffer availability haircuts        stress_projs: dict[int, pd.DataFrame] = {}        for gw, df in horizon_projections.items():            df_stress = df.copy()            if gw > target_gw and "expected_points" in df_stress.columns:                if "chance_of_playing" in df_stress.columns:                    cop = df_stress["chance_of_playing"].fillna(100.0)                elif "p_play" in df_stress.columns:                    cop = df_stress["p_play"].fillna(1.0) * 100.0                else:                    cop = pd.Series(100.0, index=df_stress.index)                doubt_mask = cop < 100.0                df_stress.loc[doubt_mask, "expected_points"] = (                    df_stress.loc[doubt_mask, "expected_points"] * 0.50                ).round(2)            stress_projs[gw] = df_stress        scenarios.append(            StochasticScenario(                name="availability_stress",                probability=0.25,                description="Availability stress: flagged or carrying knocks suffer delayed returns or reduced appearances.",                scenario_projections=stress_projs,            )        )        return scenarios    def evaluate_candidates(        self,        candidate_plans: list[dict[str, Any]],        scenarios: list[StochasticScenario],        target_gw: int,    ) -> list[StochasticPlanEvaluation]:        """        Evaluates each candidate plan across all scenarios and computes stochastic ranking.        """        # Precompute baseline roll plan scenario deltas to evaluate marginal scenario resilience        roll_cand = next(            (c for c in candidate_plans if not c.get("transfers_in") and not c.get("transfers_out")),            next(                (                    c                    for c in candidate_plans                    if "roll" in str(c.get("source", "")).lower() or "roll" in str(c.get("label", "")).lower()                ),                None,            ),        )        nominal_sc = next((s for s in scenarios if s.name == "nominal"), scenarios[0] if scenarios else None)        roll_trajectory_deltas: dict[str, float] = {}        roll_single_deltas: dict[str, float] = {}        if roll_cand:            if "trajectory" in roll_cand and roll_cand["trajectory"]:                for sc in scenarios:                    delta = 0.0                    for act in roll_cand["trajectory"]:                        raw_gw = act.get("gameweek") if isinstance(act, dict) else getattr(act, "gameweek", None)                        gw = int(raw_gw) if raw_gw is not None else target_gw                        raw_starters = getattr(act, "starters", None) or (                            act.get("starters") if isinstance(act, dict) else []                        )                        gw_starters = [int(p) for p in raw_starters] if raw_starters else []                        raw_cap = getattr(act, "captain", None) or (                            act.get("captain") if isinstance(act, dict) else None                        )                        gw_cap = int(raw_cap) if raw_cap else None                        nom_df = nominal_sc.scenario_projections.get(gw) if nominal_sc else None                        sc_df = sc.scenario_projections.get(gw)                        if nom_df is not None and sc_df is not None and gw_starters:                            nom_xp_map = dict(                                zip(                                    nom_df["element"].astype(int), nom_df["expected_points"].astype(float), strict=False                                )                            )                            sc_xp_map = dict(                                zip(sc_df["element"].astype(int), sc_df["expected_points"].astype(float), strict=False)                            )                            nom_pts = sum(nom_xp_map.get(p, 0.0) for p in gw_starters) + (                                nom_xp_map.get(gw_cap, 0.0) if gw_cap else 0.0                            )                            sc_pts = sum(sc_xp_map.get(p, 0.0) for p in gw_starters) + (                                sc_xp_map.get(gw_cap, 0.0) if gw_cap else 0.0                            )                            delta += sc_pts - nom_pts                    roll_trajectory_deltas[sc.name] = delta            else:                roll_starters = []                roll_cap = None                if "starting_xi" in roll_cand and roll_cand["starting_xi"]:                    roll_starters = [                        int(p.get("element", p) if isinstance(p, dict) else p) for p in roll_cand["starting_xi"]                    ]                    roll_cap = int(roll_cand.get("captain_id") or roll_cand.get("captain") or 0) or None                elif "starters" in roll_cand and roll_cand["starters"]:                    roll_starters = [                        int(p.get("element", p) if isinstance(p, dict) else p) for p in roll_cand["starters"]                    ]                    roll_cap = int(roll_cand.get("captain_id", 0)) or None                nom_df = nominal_sc.scenario_projections.get(target_gw) if nominal_sc else None                nom_xp_map = (                    dict(zip(nom_df["element"].astype(int), nom_df["expected_points"].astype(float), strict=False))                    if nom_df is not None and "element" in nom_df.columns and "expected_points" in nom_df.columns                    else {}                )                nom_squad_pts = (                    sum(nom_xp_map.get(p, 0.0) for p in roll_starters)                    + (nom_xp_map.get(roll_cap, 0.0) if roll_cap else 0.0)                    if roll_starters and nom_xp_map                    else None                )                if nom_squad_pts is not None:                    for sc in scenarios:                        if target_gw in sc.scenario_projections:                            sc_df = sc.scenario_projections[target_gw]                            if "element" in sc_df.columns and "expected_points" in sc_df.columns:                                sc_xp_map = dict(                                    zip(                                        sc_df["element"].astype(int),                                        sc_df["expected_points"].astype(float),                                        strict=False,                                    )                                )                                sc_squad_pts = sum(sc_xp_map.get(p, 0.0) for p in roll_starters) + (                                    sc_xp_map.get(roll_cap, 0.0) if roll_cap else 0.0                                )                                roll_single_deltas[sc.name] = sc_squad_pts - nom_squad_pts        results: list[StochasticPlanEvaluation] = []        for cand in candidate_plans:            label = cand.get("label", cand.get("source", "Plan"))            plan_id = cand.get("plan_id", label)            t_in = cand.get("transfers_in", [])            t_out = cand.get("transfers_out", [])            hit = int(cand.get("hit_cost", 0) or 0)            base_xp = float(cand.get("expected_gain", 0.0) or 0.0) - hit            # Dynamic Per-Player Scenario Rescoring            scenario_utils: dict[str, float] = {}            if "trajectory" in cand and len(cand["trajectory"]) > 0:                for sc in scenarios:                    sc_delta = 0.0                    for act in cand["trajectory"]:                        raw_gw = act.get("gameweek") if isinstance(act, dict) else getattr(act, "gameweek", None)                        gw = int(raw_gw) if raw_gw is not None else target_gw                        raw_starters = getattr(act, "starters", None) or (                            act.get("starters") if isinstance(act, dict) else []                        )                        gw_starters = [int(p) for p in raw_starters] if raw_starters else []                        raw_cap = getattr(act, "captain", None) or (                            act.get("captain") if isinstance(act, dict) else None                        )                        gw_cap = int(raw_cap) if raw_cap else None                        nom_df = nominal_sc.scenario_projections.get(gw) if nominal_sc else None                        sc_df = sc.scenario_projections.get(gw)                        if nom_df is not None and sc_df is not None and gw_starters:                            nom_xp_map = dict(                                zip(                                    nom_df["element"].astype(int), nom_df["expected_points"].astype(float), strict=False                                )                            )                            sc_xp_map = dict(                                zip(sc_df["element"].astype(int), sc_df["expected_points"].astype(float), strict=False)                            )                            nom_pts = sum(nom_xp_map.get(p, 0.0) for p in gw_starters) + (                                nom_xp_map.get(gw_cap, 0.0) if gw_cap else 0.0                            )                            sc_pts = sum(sc_xp_map.get(p, 0.0) for p in gw_starters) + (                                sc_xp_map.get(gw_cap, 0.0) if gw_cap else 0.0                            )                            sc_delta += sc_pts - nom_pts                    # Marginal scenario resilience relative to baseline roll plan                    roll_delta = roll_trajectory_deltas.get(sc.name, 0.0) if roll_cand else 0.0                    relative_scenario_gain = sc_delta - roll_delta                    scenario_utils[sc.name] = round(base_xp + relative_scenario_gain, 2)            else:                starters = []                cap = None                if "starting_xi" in cand and cand["starting_xi"]:                    starters = [int(p.get("element", p) if isinstance(p, dict) else p) for p in cand["starting_xi"]]                    cap = int(cand.get("captain_id") or cand.get("captain") or 0) or None                elif "starters" in cand and cand["starters"]:                    starters = [int(p.get("element", p) if isinstance(p, dict) else p) for p in cand["starters"]]                    cap = int(cand.get("captain_id", 0)) or None                nom_df = nominal_sc.scenario_projections.get(target_gw) if nominal_sc else None                nom_xp_map = (                    dict(zip(nom_df["element"].astype(int), nom_df["expected_points"].astype(float), strict=False))                    if nom_df is not None and "element" in nom_df.columns and "expected_points" in nom_df.columns                    else {}                )                nom_squad_pts = (                    sum(nom_xp_map.get(p, 0.0) for p in starters) + (nom_xp_map.get(cap, 0.0) if cap else 0.0)                    if starters and nom_xp_map                    else None                )                for sc in scenarios:                    sc_name = sc.name                    if nom_squad_pts is not None and target_gw in sc.scenario_projections:                        sc_df = sc.scenario_projections[target_gw]                        if "element" in sc_df.columns and "expected_points" in sc_df.columns:                            sc_xp_map = dict(                                zip(sc_df["element"].astype(int), sc_df["expected_points"].astype(float), strict=False)                            )                            sc_squad_pts = sum(sc_xp_map.get(p, 0.0) for p in starters) + (                                sc_xp_map.get(cap, 0.0) if cap else 0.0                            )                            sc_delta = sc_squad_pts - nom_squad_pts                            roll_delta = roll_single_deltas.get(sc_name, 0.0) if roll_cand else 0.0                            relative_scenario_gain = sc_delta - roll_delta                            sc_util = base_xp + relative_scenario_gain                        else:                            sc_util = base_xp                    else:                        # Fallback for synthetic plans lacking starter IDs                        if sc_name == "nominal":                            sc_util = base_xp                        elif sc_name == "rotation_shock":                            haircut = 0.10 if len(t_in) > 0 else 0.05                            penalty = max(abs(base_xp), float(cand.get("expected_gain", 0.0) or 0.0)) * haircut                            sc_util = base_xp - penalty                        else:                            haircut = 0.15 if len(t_in) > 0 else 0.10                            penalty = max(abs(base_xp), float(cand.get("expected_gain", 0.0) or 0.0)) * haircut                            sc_util = base_xp - penalty                    scenario_utils[sc_name] = round(sc_util, 2)            probs = np.array([sc.probability for sc in scenarios])            if np.sum(probs) > 0:                probs = probs / np.sum(probs)            utils = np.array([scenario_utils[sc.name] for sc in scenarios])            expected_u = float(np.dot(probs, utils))            worst_u = float(np.min(utils))            # CVaR (alpha = 0.50 downside tail)            order = np.argsort(utils)            s_probs = probs[order]            s_utils = utils[order]            acc = 0.0            tail_sum = 0.0            alpha = 0.50            for p, u in zip(s_probs, s_utils, strict=False):                take_p = min(p, alpha - acc)                tail_sum += take_p * u                acc += take_p                if acc >= alpha - 1e-9:                    break            cvar_50 = float(tail_sum / alpha) if alpha > 0 else worst_u            # Robustness: E[U] - lambda * DownsideSemiDev(U)            # Uses downside semi-deviation sqrt(E[min(0, U - u_bar)^2]) so high upside variance is not penalized            downside_diff = np.minimum(0.0, utils - expected_u)            dispersion = float(np.sqrt(max(0.0, float(np.dot(probs, downside_diff**2)))))            robustness = round(expected_u - self.risk_lambda * dispersion, 2)            tier = "ROBUST_DOMINANT" if robustness >= 0.5 else ("VIABLE" if expected_u >= 0 else "FRAGILE_SUBOPTIMAL")            results.append(                StochasticPlanEvaluation(                    plan_id=plan_id,                    label=label,                    transfers_in=t_in,                    transfers_out=t_out,                    hit_cost=hit,                    scenario_utilities=scenario_utils,                    expected_stochastic_utility=round(expected_u, 2),                    downside_worst_case=round(worst_u, 2),                    downside_cvar=round(cvar_50, 2),                    robustness_index=robustness,                    recommendation_tier=tier,                )            )        # Sort by robustness index descending        results.sort(key=lambda r: r.robustness_index, reverse=True)        return results    def generate_pareto_frontier(        self,        candidate_plans: list[dict[str, Any]],        scenarios: list[StochasticScenario],        target_gw: int,        lambda_grid: list[float] | None = None,        deduplicate: bool = False,    ) -> list[ParetoPlanPoint]:        """        Sweeps risk aversion parameters to generate the non-dominated Pareto Frontier:        - lambda = -0.50: MAX_UPSIDE (chasing pack / differentials / P90 upside)        - lambda = 0.00: RISK_NEUTRAL (pure mean expected points)        - lambda = 0.35: BALANCED_CONTENDER (optimal risk-adjusted trade-off)        - lambda = 1.00: DEFENSIVE_PRESERVATION (defending league lead, high floor)        """        if not candidate_plans or not scenarios:            return []        grid = lambda_grid or [-0.50, 0.00, 0.35, 1.00]        points: list[ParetoPlanPoint] = []        profile_map = {            -0.50: ("MAX_UPSIDE", "Chasing pack posture: maximizes differential ceiling and P90 upside."),            0.00: ("RISK_NEUTRAL", "Pure expected points maximization with zero variance penalty."),            0.35: ("BALANCED_CONTENDER", "Optimal compromise: balances high baseline xP against downside CVaR."),            1.00: (                "DEFENSIVE_PRESERVATION",                "Defending lead posture: heavily penalizes downside dispersion and rotation variance.",            ),        }        # 1. Filter Pareto frontier candidates for strict Pareto non-domination        filtered_candidates = self.filter_pareto_candidates(candidate_plans, scenarios, target_gw)        if not filtered_candidates:            filtered_candidates = candidate_plans        orig_lambda = self.risk_lambda        try:            for lam in grid:                prof_name, rationale = profile_map.get(                    round(lam, 2),                    ("CUSTOM_PROFILE", f"Custom risk aversion weighting lambda={lam:.2f}"),                )                self.risk_lambda = lam                evals = self.evaluate_candidates(filtered_candidates, scenarios, target_gw)                if not evals:                    continue                best = max(evals, key=lambda e: e.robustness_index)                points.append(                    ParetoPlanPoint(                        lambda_risk=round(lam, 2),                        strategy_profile=prof_name,                        best_plan_id=best.plan_id,                        label=best.label,                        expected_stochastic_utility=best.expected_stochastic_utility,                        downside_worst_case=best.downside_worst_case,                        downside_cvar=best.downside_cvar,                        robustness_score=best.robustness_index,                        transfers_in=best.transfers_in,                        transfers_out=best.transfers_out,                        hit_cost=best.hit_cost,                        rationale=rationale,                    )                )        finally:            self.risk_lambda = orig_lambda        if deduplicate:            points = self.filter_pareto_frontier_points(points)        return points    def filter_pareto_candidates(        self,        candidate_plans: list[dict[str, Any]],        scenarios: list[StochasticScenario],        target_gw: int,    ) -> list[dict[str, Any]]:        """        Filters candidate plans for strict Pareto non-domination and removes duplicates.        A candidate plan A dominates plan B if A achieves >= utility than B in every scenario        and > utility in at least one scenario.        """        if not candidate_plans:            return []        # 1. Deduplicate identical candidate plans        unique_cands: list[dict[str, Any]] = []        seen_keys: set[tuple] = set()        for cand in candidate_plans:            t_in = tuple(sorted(cand.get("transfers_in", [])))            t_out = tuple(sorted(cand.get("transfers_out", [])))            hit = int(cand.get("hit_cost", 0) or 0)            gain = round(float(cand.get("expected_gain", 0.0) or 0.0), 2)            pid = cand.get("plan_id", cand.get("label", ""))            key = (pid, t_in, t_out, hit, gain)            if key in seen_keys:                continue            seen_keys.add(key)            unique_cands.append(cand)        if len(unique_cands) <= 1:            return unique_cands        # 2. Evaluate candidates across scenarios to check strict Pareto domination        evals = self.evaluate_candidates(unique_cands, scenarios, target_gw)        eval_map = {e.plan_id: e for e in evals}        non_dominated: list[dict[str, Any]] = []        for i, c1 in enumerate(unique_cands):            pid1 = c1.get("plan_id", c1.get("label"))            e1 = eval_map.get(pid1)            if not e1:                non_dominated.append(c1)                continue            is_dominated = False            for j, c2 in enumerate(unique_cands):                if i == j:                    continue                pid2 = c2.get("plan_id", c2.get("label"))                e2 = eval_map.get(pid2)                if not e2:                    continue                sc_keys = set(e1.scenario_utilities.keys()) & set(e2.scenario_utilities.keys())                if not sc_keys:                    continue                ge_all = all(e2.scenario_utilities[s] >= e1.scenario_utilities[s] - 1e-6 for s in sc_keys)                gt_any = any(e2.scenario_utilities[s] > e1.scenario_utilities[s] + 1e-6 for s in sc_keys)                if ge_all and gt_any:                    is_dominated = True                    break            if not is_dominated:                non_dominated.append(c1)        return non_dominated if non_dominated else unique_cands    @staticmethod    def filter_pareto_frontier_points(points: list[ParetoPlanPoint]) -> list[ParetoPlanPoint]:        """        Filters a list of ParetoPlanPoints for strict Pareto non-domination and removes duplicates.        A point A dominates point B if A is >= in all performance objectives        (expected utility, downside CVaR, downside worst case) and > in at least one.        """        if not points:            return []        unique_points: list[ParetoPlanPoint] = []        seen_plan_ids: set[str] = set()        seen_coords: set[tuple[float, float, float]] = set()        for pt in points:            coord = (                round(pt.expected_stochastic_utility, 3),                round(pt.downside_cvar, 3),                round(pt.downside_worst_case, 3),            )            if pt.best_plan_id in seen_plan_ids or coord in seen_coords:                continue            seen_plan_ids.add(pt.best_plan_id)            seen_coords.add(coord)            unique_points.append(pt)        pareto_optimal: list[ParetoPlanPoint] = []        for i, pt_i in enumerate(unique_points):            is_dominated = False            for j, pt_j in enumerate(unique_points):                if i == j:                    continue                ge_all = (                    pt_j.expected_stochastic_utility >= pt_i.expected_stochastic_utility - 1e-6                    and pt_j.downside_cvar >= pt_i.downside_cvar - 1e-6                    and pt_j.downside_worst_case >= pt_i.downside_worst_case - 1e-6                )                gt_any = (                    pt_j.expected_stochastic_utility > pt_i.expected_stochastic_utility + 1e-6                    or pt_j.downside_cvar > pt_i.downside_cvar + 1e-6                    or pt_j.downside_worst_case > pt_i.downside_worst_case + 1e-6                )                if ge_all and gt_any:                    is_dominated = True                    break            if not is_dominated:                pareto_optimal.append(pt_i)        return pareto_optimalstochastic_optimizer = StochasticScenarioOptimizer()